arguments.new_str:
namespace Payments;

public interface IPaymentProcessor
{
    Task<string> SubmitChargeAsync(string cardToken, decimal amount);
    Task<string> SubmitRefundAsync(string chargeId);
}

public sealed class PaymentGateway
{
    private readonly IPaymentProcessor _processor;

    public PaymentGateway(IPaymentProcessor processor)
    {
        ArgumentNullException.ThrowIfNull(processor);
        _processor = processor;
    }

    public async Task<ChargeResult> ChargeAsync(string cardToken, decimal amount)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(cardToken);
        if (amount <= 0)
            throw new ArgumentOutOfRangeException(nameof(amount), "Amount must be positive.");

        try
        {
            var chargeId = await _processor.SubmitChargeAsync(cardToken, amount);
            return new ChargeResult(chargeId, Success: true);
        }
        catch (Exception)
        {
            return new ChargeResult(string.Empty, Success: false);
        }
    }

    public async Task<RefundResult> RefundAsync(string chargeId)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(chargeId);

        try
        {
            var refundId = await _processor.SubmitRefundAsync(chargeId);
            return new RefundResult(refundId, Success: true);
        }
        catch (Exception)
        {
            return new RefundResult(string.Empty, Success: false);
        }
    }

    public WebhookResult ProcessWebhook(string eventType, string payload)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(eventType);
        ArgumentException.ThrowIfNullOrWhiteSpace(payload);

        return eventType switch
        {
            "charge.succeeded" => new WebhookResult(EventType: eventType, Handled: true),
            "charge.failed" => new WebhookResult(EventType: eventType, Handled: true),
            "refund.completed" => new WebhookResult(EventType: eventType, Handled: true),
            _ => new WebhookResult(EventType: eventType, Handled: false),
        };
    }
}

public record ChargeResult(string ChargeId, bool Success);
public record RefundResult(string RefundId, bool Success);
public record WebhookResult(string EventType, bool Handled);

