using Payments;

namespace Payments.Tests;

internal sealed class FakePaymentProcessor : IPaymentProcessor
{
    public string? ChargeIdToReturn { get; set; } = "ch_abc123";
    public string? RefundIdToReturn { get; set; } = "rf_xyz789";
    public Exception? ExceptionToThrow { get; set; }

    public string? LastCardToken { get; private set; }
    public decimal LastAmount { get; private set; }
    public string? LastChargeId { get; private set; }

    public Task<string> SubmitChargeAsync(string cardToken, decimal amount)
    {
        if (ExceptionToThrow is not null)
            throw ExceptionToThrow;

        LastCardToken = cardToken;
        LastAmount = amount;
        return Task.FromResult(ChargeIdToReturn!);
    }

    public Task<string> SubmitRefundAsync(string chargeId)
    {
        if (ExceptionToThrow is not null)
            throw ExceptionToThrow;

        LastChargeId = chargeId;
        return Task.FromResult(RefundIdToReturn!);
    }
}

