using Payments;

namespace Payments.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private readonly FakePaymentProcessor _processor;
    private readonly PaymentGateway _gateway;

    public PaymentGatewayTests()
    {
        _processor = new FakePaymentProcessor();
        _gateway = new PaymentGateway(_processor);
    }

    // ──────────────────────────────────────
    //  Constructor validation
    // ──────────────────────────────────────

    [TestMethod]
    public void Ctor_NullProcessor_Throws()
    {
        Assert.ThrowsExactly<ArgumentNullException>(() => new PaymentGateway(null!));
    }

    // ──────────────────────────────────────
    //  ChargeAsync – happy path
    // ──────────────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_ValidInput_ReturnsSuccessWithChargeId()
    {
        _processor.ChargeIdToReturn = "ch_test_001";

        var result = await _gateway.ChargeAsync("tok_visa", 49.99m);

        Assert.IsTrue(result.Success);
        Assert.AreEqual("ch_test_001", result.ChargeId);
    }

    [TestMethod]
    public async Task ChargeAsync_ValidInput_ForwardsCardTokenAndAmount()
    {
        await _gateway.ChargeAsync("tok_mastercard", 100m);

        Assert.AreEqual("tok_mastercard", _processor.LastCardToken);
        Assert.AreEqual(100m, _processor.LastAmount);
    }

    // ──────────────────────────────────────
    //  ChargeAsync – validation errors
    // ──────────────────────────────────────

    [TestMethod]
    [DataRow(null, DisplayName = "Null token")]
    [DataRow("", DisplayName = "Empty token")]
    [DataRow("   ", DisplayName = "Whitespace token")]
    public async Task ChargeAsync_InvalidToken_Throws(string? badToken)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(badToken!, 10m));
    }

    [TestMethod]
    [DataRow(0, DisplayName = "Zero amount")]
    [DataRow(-5.00, DisplayName = "Negative amount")]
    public async Task ChargeAsync_InvalidAmount_ThrowsOutOfRange(double badAmount)
    {
        await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_visa", (decimal)badAmount));
    }

    // ──────────────────────────────────────
    //  ChargeAsync – processor failure
    // ──────────────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_ProcessorThrows_ReturnsFailure()
    {
        _processor.ExceptionToThrow = new InvalidOperationException("gateway down");

        var result = await _gateway.ChargeAsync("tok_visa", 25m);

        Assert.IsFalse(result.Success);
        Assert.AreEqual(string.Empty, result.ChargeId);
    }

    // ──────────────────────────────────────
    //  RefundAsync – happy path
    // ──────────────────────────────────────

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessWithRefundId()
    {
        _processor.RefundIdToReturn = "rf_test_001";

        var result = await _gateway.RefundAsync("ch_abc123");

        Assert.IsTrue(result.Success);
        Assert.AreEqual("rf_test_001", result.RefundId);
    }

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ForwardsChargeId()
    {
        await _gateway.RefundAsync("ch_abc123");

        Assert.AreEqual("ch_abc123", _processor.LastChargeId);
    }

    // ──────────────────────────────────────
    //  RefundAsync – validation errors
    // ──────────────────────────────────────

    [TestMethod]
    [DataRow(null, DisplayName = "Null chargeId")]
    [DataRow("", DisplayName = "Empty chargeId")]
    [DataRow("   ", DisplayName = "Whitespace chargeId")]
    public async Task RefundAsync_InvalidChargeId_Throws(string? badId)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(badId!));
    }

    // ──────────────────────────────────────
    //  RefundAsync – processor failure
    // ──────────────────────────────────────

    [TestMethod]
    public async Task RefundAsync_ProcessorThrows_ReturnsFailure()
    {
        _processor.ExceptionToThrow = new InvalidOperationException("refund failed");

        var result = await _gateway.RefundAsync("ch_abc123");

        Assert.IsFalse(result.Success);
        Assert.AreEqual(string.Empty, result.RefundId);
    }

    // ──────────────────────────────────────
    //  ProcessWebhook – known event types
    // ──────────────────────────────────────

    [TestMethod]
    [DataRow("charge.succeeded", DisplayName = "charge.succeeded")]
    [DataRow("charge.failed", DisplayName = "charge.failed")]
    [DataRow("refund.completed", DisplayName = "refund.completed")]
    public void ProcessWebhook_KnownEvent_ReturnsHandled(string eventType)
    {
        var result = _gateway.ProcessWebhook(eventType, "{\"id\":\"evt_1\"}");

        Assert.IsTrue(result.Handled);
        Assert.AreEqual(eventType, result.EventType);
    }

    // ──────────────────────────────────────
    //  ProcessWebhook – unknown event type
    // ──────────────────────────────────────

    [TestMethod]
    public void ProcessWebhook_UnknownEvent_ReturnsNotHandled()
    {
        var result = _gateway.ProcessWebhook("customer.created", "{\"id\":\"evt_2\"}");

        Assert.IsFalse(result.Handled);
        Assert.AreEqual("customer.created", result.EventType);
    }

    // ──────────────────────────────────────
    //  ProcessWebhook – validation errors
    // ──────────────────────────────────────

    [TestMethod]
    [DataRow(null, "{}", DisplayName = "Null eventType")]
    [DataRow("", "{}", DisplayName = "Empty eventType")]
    [DataRow("charge.succeeded", null, DisplayName = "Null payload")]
    [DataRow("charge.succeeded", "", DisplayName = "Empty payload")]
    public void ProcessWebhook_InvalidArgs_Throws(string? eventType, string? payload)
    {
        Assert.ThrowsExactly<ArgumentException>(
            () => _gateway.ProcessWebhook(eventType!, payload!));
    }
}

